/* 日経・ダウだけを拡張。元の銀・プラチナの描画・計算はそのまま使用。 */
'use strict';
const originalSection=section, originalIndexSignals=indexSignals, originalExitView=exitView;
function autoHealth(){const a=state.indices,s=a.autoStatus;if(a.manualCSV)return {ok:true,manual:true};if(a.autoError)return {ok:false,error:a.autoError};if(!s)return {ok:false,error:'自動更新の状態をまだ確認できません。'};const age=Date.now()-Date.parse(s.last_attempt_at);if(!Number.isFinite(age)||age>36*3600000||age<-5*60000)return {ok:false,error:'更新確認から36時間以上経過しています。定期実行・再公開の状態を確認してください。'};if(s.update_status==='DATA UPDATE ERROR'||!s.last_success_at)return {ok:false,error:s.error||'正常更新を確認できません。'};return {ok:true};}
section=function(kind){let html=originalSection(kind);if(kind!=='indices')return html;const a=state.indices,s=a.autoStatus,h=autoHealth(),r=a.data.at(-1);const signal=r.c2?'B + C2 SIGNAL':r.b?'B SIGNAL':'NO SIGNAL';const banner=h.manual?'<div class="auto-manual">手動CSV表示中。自動データへの切替は下のボタンを押してください。</div>':h.ok?`<div class="auto-ok"><strong>${signal}</strong><span>${s.update_status==='NO_NEW_DATA'?'公式データ確認済み / 新しい取引日なし':'公式データ更新済み'}　価格日 ${esc(s.data_date)}</span></div>`:`<div class="auto-failed" role="alert"><strong>DATA UPDATE ERROR</strong><span>最終正常更新：${esc(s?.last_success_at||'未確認')} / 正常価格日：${esc(s?.data_date||'未確認')}</span><p>${esc(h.error)}</p><span>下の数値は過去の参考値です。シグナル・候補は無効です。</span></div>`;
const metadata=`<div class="auto-meta"><span>最終試行：${esc(s?.last_attempt_at||'未確認')}</span><span>最終正常更新：${esc(s?.last_success_at||'未確認')}</span><span>更新予定：毎日10:30 日本時間</span><button type="button" data-auto-reload>自動データに戻す / 再読み込み</button></div><div class="auto-products">${s?.products?esc(s.products.ny_dow.name)+' / '+esc(s.products.nikkei225.name):'対象：固定2026年限（確認待ち）'}</div>`;
html=html.replace('<div class="metrics">',banner+metadata+'<div class="metrics">');if(!h.ok)html=html.replace('最新サヤ','保存済みサヤ（参考）').replace('最新サヤを仮の建値として表示','保存済みサヤを仮の建値として表示');const values=`<div class="auto-indicators"><div><span>20MA</span><strong>${num(r.ma20,1)}</strong></div><div><span>50MA</span><strong>${num(r.ma50,1)}</strong></div><div><span>10営業日サヤ変化</span><strong>${sign(r.change10,0)} pt</strong></div></div>`;html=html.replace('<div class="grid">',values+'<div class="grid">');html=html.replace('<details>','<details><summary>毎日更新の状態とシグナルの読み方</summary><p>NO SIGNAL：B/C2とも不成立。B SIGNAL：B成立・C2不成立。B + C2 SIGNAL：BとC2両方成立。C2 SIGNAL単独は構造上発生しません（C2はBの条件をすべて満たします）。</p><p>毎日取得して検証したCSV/JSONを再公開すると反映されます。画面は5分ごと・画面に戻ったときにJSONを再確認します。定期実行や公開が止まると、36時間経過後にDATA UPDATE ERRORを表示します。土日・休場日は新しい価格を作らず「新しい取引日なし」と表示します。</p><p>自動表示のポジションはOOS仮想保有です。実口座へ接続していません。実際の建値は手入力してください。2026年限の取引最終日後は自動切替せず停止します。</p></details><details>');return html;};
indexSignals=function(r,d){if(!autoHealth().ok)return '<div class="signal"><strong>判定停止</strong><p>DATA UPDATE ERROR。保存済みデータの過去シグナルを現在のエントリー候補として扱いません。</p></div>';return originalIndexSignals(r,d);};
exitView=function(kind){const html=originalExitView(kind);if(kind!=='indices')return html;const h=autoHealth();return (h.ok?'':'<p class="auto-exit-warning">更新エラー中：決済目安は保存済み価格を使った参考値です。</p>')+(h.ok?html:html.replaceAll('最新サヤ','保存済みサヤ'));};
let autoBusy=false;
function refreshIndices(){const el=document.querySelector('#indices');if(el&&state.indices.rows.length){el.outerHTML=section('indices');draw('indices');}}
async function loadAuto(force=false){if(autoBusy||state.indices.manualCSV&&!force)return;autoBusy=true;try{let s;if(location.protocol==='file:'&&typeof EMBEDDED_INDEX_STATUS!=='undefined'){s=EMBEDDED_INDEX_STATUS;}else{const response=await fetch('./dow-nikkei-status.json',{cache:'no-store'});if(!response.ok)throw Error('更新状態JSONを取得できません（HTTP '+response.status+'）。');s=await response.json();}if(!s||!Array.isArray(s.history)||!s.history.length)throw Error('自動更新データに価格履歴がありません。');const columns=['date','ny_dow_open','ny_dow_close','nikkei225_open','nikkei225_close'],text=columns.join(',')+'\n'+s.history.map(r=>columns.map(k=>r[k]??'').join(',')).join('\n');const rows=E.parse(text,'indices'),last=E.derive(rows,'indices').at(-1);if(s.latest&&(s.latest.date!==last.date||s.latest.spread!==last.spread||Boolean(s.latest.signal_b)!==last.b||Boolean(s.latest.signal_c2)!==last.c2))throw Error('自動更新JSONの価格とシグナルが一致しません。');state.indices.rows=rows;state.indices.autoStatus=s;state.indices.autoError='';state.indices.name='TFX公式自動取得';if(force)state.indices.manualCSV=false;refreshIndices();}catch(error){state.indices.autoError=error.message;refreshIndices();}finally{autoBusy=false;}}
document.addEventListener('change',async event=>{if(event.target.dataset.import!=='indices')return;const file=event.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)return;const rows=E.parse(await file.text(),'indices');if(rows.length>20000)return;state.indices.manualCSV=true;refreshIndices();}catch(error){/* 無効CSVでは自動データの状態を保持。 */}});
document.addEventListener('click',event=>{if(event.target.closest('[data-auto-reload]'))loadAuto(true);});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadAuto();});
setInterval(()=>loadAuto(),5*60000);loadAuto();
